// ---------------------------------------------------------------------------
const { data: quizzes } = await db.from('quizzes').select('id, capsule_id, title');
const { data: caps } = await db.from('capsules').select('id, title');
const { data: existingQs } = await db.from('quiz_questions').select('id, quiz_id, question_type, correct_answer');

const capTitle = new Map(caps.map((c) => [c.id, c.title]));

console.log(APPLY ? '=== APPLYING ===\n' : '=== PREVIEW (pass --apply) ===\n');

// Repair the pre-existing question, which stored {answer: true} where the grader compares
// against the string "true" — so it could never be marked correct.
for (const q of existingQs) {
  const ca = q.correct_answer;
  if (ca && typeof ca === 'object' && 'answer' in ca) {
    const fixed = String(ca.answer);
    console.log(`repairing legacy answer format: ${JSON.stringify(ca)} -> "${fixed}"`);
    if (APPLY) await db.from('quiz_questions').update({ correct_answer: fixed }).eq('id', q.id);
  }
}

const hasQuestions = new Set(existingQs.map((q) => q.quiz_id));
let written = 0;
let quizzesFilled = 0;

for (const quiz of quizzes) {
  if (!quiz.capsule_id || hasQuestions.has(quiz.id)) continue;
  const title = capTitle.get(quiz.capsule_id) ?? '';

  const key = Object.keys(BANK).find((k) => title.toLowerCase().includes(k.toLowerCase()));
  if (!key) continue;

  const questions = BANK[key];
  console.log(`  ${title.slice(0, 52).padEnd(54)} ${questions.length} questions`);
  quizzesFilled++;
  written += questions.length;

  if (!APPLY) continue;

  const { error } = await db.from('quiz_questions').insert(
    questions.map((q, i) => ({ ...q, quiz_id: quiz.id, order_index: i }))
  );
  if (error) console.log(`     FAILED: ${error.message}`);
}

console.log(`\n${APPLY ? 'Wrote' : 'Would write'} ${written} questions across ${quizzesFilled} quizzes.`);
console.log('All still UNPUBLISHED. Review in Admin > Quizzes, correct anything that');
console.log('contradicts your lecture, then publish. Nothing is visible to a learner until you do.');
